const state = { data: [], selectedDate: null, selectedSector: null, query: "", sort: "desc", range: 5 };
const $ = s => document.querySelector(s);
const fmt = n => `${n > 0 ? "+" : ""}${n.toFixed(2)}%`;
const fmtDate = d => new Intl.DateTimeFormat("ko-KR", { year:"numeric", month:"long", day:"numeric", weekday:"short" }).format(new Date(`${d}T12:00:00`));

async function init(){ renderLiveState(); state.data = await marketRepository.getMarketDays(); state.selectedDate = state.data[0].date; bindEvents(); render(); }
function currentDay(){ return state.data.find(d => d.date === state.selectedDate); }
function periodDays(){ const index=state.data.findIndex(d=>d.date===state.selectedDate); const count=state.range==="all"?state.data.length:Number(state.range); return state.data.slice(index,index+count); }
function rankedSectors(){
  const days=periodDays(), downDays=days.filter(d=>d.kospi<0), groups=new Map();
  downDays.forEach(day=>day.sectors.forEach(sector=>{ const item=groups.get(sector.name)||{name:sector.name,returns:[],stocks:new Map(),hits:0}; item.returns.push(sector.returnRate); item.hits+=1; sector.stocks.forEach(stock=>{const saved=item.stocks.get(stock.code)||{...stock,returns:[]};saved.returns.push(stock.returnRate);item.stocks.set(stock.code,saved)});groups.set(sector.name,item) }));
  const kospiDown=downDays.reduce((sum,day)=>sum+day.kospi,0);
  return [...groups.values()].map(sector=>{const average=sector.returns.reduce((a,b)=>a+b,0)/sector.returns.length;const cumulative=sector.returns.reduce((a,b)=>a+b,0);const persistence=sector.hits/Math.max(1,downDays.length)*100;const excess=cumulative-kospiDown;const score=Math.min(99,Math.round(Math.max(0,excess)*6+persistence*.3+Math.max(0,average)*5));const stocks=[...sector.stocks.values()].map(stock=>({...stock,returnRate:stock.returns.reduce((a,b)=>a+b,0)/stock.returns.length}));return {...sector,returnRate:cumulative,average,persistence,excess,score,stocks}}).sort((a,b)=>b.score-a.score);
}
function filteredSectors(){const q=state.query.trim().toLowerCase();return rankedSectors().filter(s=>!q||s.name.toLowerCase().includes(q)||s.stocks.some(x=>x.name.toLowerCase().includes(q)||x.code.includes(q)))}
function render(){renderLiveState();renderOutlook();renderSummary();renderSectors();renderStocks();renderNews();renderHeatmap()}
function renderLiveState(){const status=$("#liveStatus"),date=$("#liveDate"),button=$("#refreshBtn");if(!status)return;status.textContent=LIVE_STATE.message;date.textContent=DAILY_OUTLOOK.asOf?.slice(0,10).replaceAll("-",".")||"—";const box=status.closest(".market-state");box.classList.toggle("is-loading",LIVE_STATE.status==="loading");box.classList.toggle("is-fallback",LIVE_STATE.status==="fallback");if(button)button.disabled=LIVE_STATE.status==="loading"}
function renderOutlook(){
  const view=DAILY_OUTLOOK;
  $("#outlookAsOf").textContent=`${view.asOf} 기준 · 다음 개장 전 관점`;
  $("#outlookConfidence").textContent=`관심도 ${view.focus.score} / 100`;
  $("#focusSector").textContent=view.focus.sector; $("#focusStatus").textContent=view.focus.status; $("#focusThesis").textContent=view.focus.thesis;
  $("#focusPositives").innerHTML=view.focus.positives.map(x=>`<span>${x}</span>`).join("");
  $("#focusChecks").innerHTML=view.focus.checks.map(x=>`<li>${x}</li>`).join("");
  $("#entryGrid").innerHTML=view.entries.map(x=>`<article class="entry-card"><div class="entry-title"><div><h3>${x.name}</h3><span>${x.code}</span></div><b>${x.appeal}<small>/100</small></b></div><div class="entry-current"><span>현재 가격<small>${x.priceLabel||"최근 확인 가격"}</small></span><strong>${x.close.toLocaleString()}원</strong></div><div class="entry-zones"><span>1차 관심 구간<strong>${x.zone1}</strong></span><span>2차 확인 구간<strong>${x.zone2}</strong></span><span class="invalid-zone">가정 무효화<strong>${x.invalid}</strong></span></div><p>${x.basis}</p></article>`).join("");
  $("#rotationFlow").innerHTML=view.rotation.map((x,i)=>`<div class="rotation-step ${x.stage==='현재 주도'?'leader-step':''}"><div class="rotation-top"><span>${String(i+1).padStart(2,'0')}</span><b>${x.stage}</b></div><h3>${x.sector}</h3><div class="signal-track"><i style="width:${x.signal}%"></i></div><p>${x.note}</p></div>`).join("");
  $("#outlookSources").innerHTML=`<span>분석 근거</span>${view.sources.map(s=>`<a href="${s.url}" target="_blank" rel="noopener">${s.label}</a>`).join("")}`;
}
function renderSummary(){const day=currentDay(),days=periodDays(),periodKospi=days.reduce((a,x)=>a+x.kospi,0),ranking=rankedSectors();$("#summaryDate").textContent=state.range==1?fmtDate(day.date):`${days.at(-1).date.slice(5)} ~ ${day.date.slice(5)}`;$("#kospiValue").textContent=fmt(periodKospi);$("#kospiValue").className=`kospi-value ${periodKospi<0?"negative":"positive"}`;$("#kospiDesc").textContent=state.range==1?(day.kospi<0?"전일 대비 하락 · 역행 섹터 탐지 대상":"전일 대비 상승 · 참고 거래일"):`선택 기간 단순 누적 · 하락 거래일 ${days.filter(x=>x.kospi<0).length}일`;$("#sectorCount").innerHTML=`${ranking.length}<span>개</span>`;$("#bestSector").textContent=ranking[0]?.name||"—";$("#averageReturn").textContent=ranking.length?`${ranking[0].score}점`:"—";if(!state.selectedSector||!ranking.some(s=>s.name===state.selectedSector))state.selectedSector=ranking[0]?.name}
function renderSectors(){const sectors=filteredSectors(),max=Math.max(...rankedSectors().map(s=>s.score),1);$("#sectorRanking").innerHTML=sectors.map((s,i)=>`<button class="sector-row ${s.name===state.selectedSector?"active":""}" data-sector="${s.name}"><span class="rank">${String(i+1).padStart(2,"0")}</span><span class="sector-main"><span class="sector-name">${s.name}</span><span class="leader">초과 ${fmt(s.excess)} · 상승 지속 ${Math.round(s.persistence)}%</span><span class="bar"><i style="width:${s.score/max*100}%"></i></span></span><span class="score"><span class="return">${s.score}점</span><small>${fmt(s.returnRate)}</small></span></button>`).join("");document.querySelectorAll(".sector-row").forEach(el=>el.onclick=()=>{state.selectedSector=el.dataset.sector;renderSectors();renderStocks();openDrawer(el.dataset.sector)})}
function renderStocks(){let sectors=filteredSectors(),stocks=[];if(state.query)stocks=sectors.flatMap(s=>s.stocks.map(x=>({...x,sector:s.name}))).filter(x=>x.name.toLowerCase().includes(state.query.toLowerCase())||x.code.includes(state.query)||x.sector.toLowerCase().includes(state.query.toLowerCase()));else{const sector=rankedSectors().find(s=>s.name===state.selectedSector)||rankedSectors()[0];stocks=(sector?.stocks||[]).map(x=>({...x,sector:sector?.name}))}stocks.sort((a,b)=>state.sort==="asc"?a.returnRate-b.returnRate:state.sort==="name"?a.name.localeCompare(b.name,"ko"):b.returnRate-a.returnRate);$("#stockTitle").textContent=state.query?"검색 종목":`${state.selectedSector||""} 대표 종목`;$("#stockTable").innerHTML=stocks.map(stock=>{const info=MARKET_INTELLIGENCE.stocks[stock.code];return `<tr class="stock-row" data-code="${stock.code}" data-name="${stock.name}"><td><span class="stock-name">${stock.name}</span><small class="code">${stock.code}</small></td><td class="price-cell">${info?info.price.toLocaleString()+"원":"—"}<small>${info?.priceDate||""}</small></td><td class="${stock.returnRate>=0?"positive":"negative"}">${fmt(stock.returnRate)}</td></tr>`}).join("");document.querySelectorAll(".stock-row").forEach(el=>el.onclick=()=>openStockProfile(el.dataset.code,el.dataset.name));$("#emptyState").hidden=stocks.length>0;$(".table-wrap").hidden=stocks.length===0}
function renderNews(){const sectorNames=[...new Set([DAILY_OUTLOOK.focus.sector,...rankedSectors().slice(0,4).map(s=>s.name)])];const items=sectorNames.flatMap(name=>(MARKET_INTELLIGENCE.news[name]||[]).map(n=>({...n,sector:name}))).slice(0,6);$("#newsGrid").innerHTML=items.length?items.map(n=>`<a class="news-card" href="${n.url}" target="_blank" rel="noopener"><div class="news-meta"><span class="news-sector">${n.sector}</span><span>${n.source}</span><span>${n.date}</span></div><h3>${n.title}</h3><p>${n.summary}</p></a>`).join(""):`<div class="empty">선택 기간 상위 섹터의 등록된 뉴스가 없습니다.</div>`}
function renderHeatmap(){$("#heatmap").innerHTML=periodDays().map(d=>{const intensity=Math.min(1,(d.sectors[0]?.returnRate||0)/4);return `<button class="heat-cell ${d.kospi>=0?"rise":""} ${d.date===state.selectedDate?"active":""}" data-date="${d.date}"><span class="heat-date">${d.date.slice(5).replace("-",".")}</span><strong class="heat-kospi ${d.kospi<0?"negative":"positive"}">${fmt(d.kospi)}</strong><span class="heat-sectors">${d.sectors.slice(0,4).map((s,i)=>`<i style="opacity:${Math.max(.25,intensity-i*.13)}"></i>`).join("")}</span></button>`}).join("");document.querySelectorAll(".heat-cell").forEach(el=>el.onclick=()=>{state.selectedDate=el.dataset.date;state.selectedSector=null;render();window.scrollTo({top:260,behavior:"smooth"})})}
function openDrawer(name){const sector=rankedSectors().find(x=>x.name===name);if(!sector)return;$("#drawerTitle").textContent=sector.name;$("#drawerReturn").textContent=`${sector.score}점 · ${fmt(sector.returnRate)}`;$("#drawerDesc").textContent=`선택 기간 KOSPI 하락일 기준 시장 대비 ${fmt(sector.excess)} 초과 수익을 기록했고, 하락일 중 ${Math.round(sector.persistence)}%에서 상승 신호가 포착됐습니다.`;$("#drawerStocks").innerHTML=sector.stocks.map(x=>`<div class="drawer-stock"><span><b>${x.name}</b><small>${x.code}</small></span><strong class="positive">${fmt(x.returnRate)}</strong></div>`).join("");$("#drawer").classList.add("open");$("#drawerBackdrop").classList.add("open");$("#drawer").setAttribute("aria-hidden","false")}
function closeDrawer(){$("#drawer").classList.remove("open");$("#drawerBackdrop").classList.remove("open");$("#drawer").setAttribute("aria-hidden","true")}
function openStockProfile(code,name){const info=MARKET_INTELLIGENCE.stocks[code];if(!info)return;$("#profileName").textContent=name;$("#profileCode").textContent=`KOSPI · ${code}`;$("#profilePrice").textContent=`${info.price.toLocaleString()}원`;$("#profilePriceDate").textContent=`${info.priceDate} 종가 기준`;$("#profileMetrics").innerHTML=`<span>시가총액<b>${info.marketCap}</b></span><span>거래량<b>${info.volume}</b></span>`;$("#profileDesc").textContent=info.description;$("#profileTags").innerHTML=info.business.map(t=>`<span>${t}</span>`).join("");$("#stockModal").classList.add("open")}
function bindEvents(){$("#sortSelect").onchange=e=>{state.sort=e.target.value;renderStocks()};$("#refreshBtn").onclick=async()=>{LIVE_STATE.status="loading";LIVE_STATE.message="데이터 새로고침 중";renderLiveState();state.data=await marketRepository.getMarketDays(true);state.selectedDate=state.data[0].date;state.selectedSector=null;render()};$("#drawerClose").onclick=closeDrawer;$("#drawerBackdrop").onclick=closeDrawer;$("#timelineJump").onclick=()=>$("#timeline").scrollIntoView({behavior:"smooth"});$("#aboutBtn").onclick=()=>$("#modal").classList.add("open");$("#modalClose").onclick=()=>$("#modal").classList.remove("open");$("#modal").onclick=e=>{if(e.target.id==="modal")e.currentTarget.classList.remove("open")};$("#stockModalClose").onclick=()=>$("#stockModal").classList.remove("open");$("#stockModal").onclick=e=>{if(e.target.id==="stockModal")e.currentTarget.classList.remove("open")};document.onkeydown=e=>{if(e.key==="Escape"){closeDrawer();$("#modal").classList.remove("open");$("#stockModal").classList.remove("open")}}}
init();
